import fs from 'node:fs';
import zlib from 'node:zlib';
const parts=Array.from({length:12},(_,i)=>`PPA${String(i+1).padStart(2,'0')}.bin`);
const src=zlib.gunzipSync(Buffer.concat(parts.map(p=>fs.readFileSync(p)))).toString('utf8');
const clean=s=>s.replace(/data:image\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+/g,'data:image/...;base64,[REMOVED]');
const needle="const playerShadowY=P.scene==='fartzone'?sy+visualBody*0.40:sy+visualBody*0.45;";
const p=src.indexOf(needle);
if(p<0)throw new Error('local player render anchor not found');
console.log('PLAYER_RENDER_POS',p);
console.log(clean(src.slice(Math.max(0,p-1800),Math.min(src.length,p+10500))));
